# Java: conditional statements (40 problems). Uses jq() from build-problems-java-core.py.
T = "Conditionals"
ONE = "One integer."
JN = [("int", "n")]
def ifelse(body):
    return body
jq("j-even-or-odd", "Even or Odd", "EASY", T, "Read an integer and print `Even` or `Odd` using if-else.", ONE, "`Even` or `Odd`.", "|n| <= 10^9",
   'if (n % 2 == 0) System.out.println("Even");\nelse System.out.println("Odd");', ["4", "7", "0", "-3", "100"], JN)
jq("j-sign-check", "Positive, Negative or Zero", "EASY", T, "Read an integer and print `Positive`, `Negative` or `Zero`.", ONE, "One word.", "|n| <= 10^9",
   'if (n > 0) System.out.println("Positive");\nelse if (n < 0) System.out.println("Negative");\nelse System.out.println("Zero");', ["5", "-8", "0", "1", "-1"], JN)
jq("j-voting-eligibility", "Voting Eligibility", "EASY", T, "Print `Eligible` if the age is 18 or more, otherwise `Not eligible`.", "One integer: age.", "`Eligible` or `Not eligible`.", "0 <= age <= 150",
   'if (n >= 18) System.out.println("Eligible");\nelse System.out.println("Not eligible");', ["18", "17", "45", "0", "100"], JN)
jq("j-largest-of-three", "Largest of Three", "EASY", T, "Read three distinct integers and print the largest with an else-if ladder.", "One line with three integers.", "The largest.", "|values| <= 10^6",
   'if (a > b && a > c) System.out.println(a);\nelse if (b > c) System.out.println(b);\nelse System.out.println(c);', ["1 2 3", "9 4 2", "5 10 7", "-1 -5 -3", "100 99 101"], [("int", "a b c")])
jq("j-leap-year", "Leap Year", "EASY", T, "A year is a leap year if it is divisible by 400, or divisible by 4 but not by 100. Print `Leap year` or `Not a leap year`.", "One integer: the year.", "`Leap year` or `Not a leap year`.", "1 <= year <= 9999",
   'if ((n % 4 == 0 && n % 100 != 0) || n % 400 == 0) System.out.println("Leap year");\nelse System.out.println("Not a leap year");', ["2024", "1900", "2000", "2023", "2100"], JN)
jq("j-vowel-or-consonant", "Vowel or Consonant", "EASY", T, "Read one letter (either case) and print `Vowel` or `Consonant`.", "One letter.", "`Vowel` or `Consonant`.", "A letter.",
   "char l = Character.toLowerCase(c);\nif (l == 'a' || l == 'e' || l == 'i' || l == 'o' || l == 'u') System.out.println(\"Vowel\");\nelse System.out.println(\"Consonant\");", ["a", "B", "E", "z", "u"], [("char", "c")])
jq("j-grading-system", "Student Grade", "EASY", T, "Grade from the percentage: 90 or more `A`, 80 or more `B`, 70 or more `C`, 60 or more `D`, otherwise `F`.", "One integer 0 to 100.", "One letter.", "0 <= n <= 100",
   'if (n >= 90) System.out.println("A");\nelse if (n >= 80) System.out.println("B");\nelse if (n >= 70) System.out.println("C");\nelse if (n >= 60) System.out.println("D");\nelse System.out.println("F");', ["95", "85", "72", "65", "30", "90", "60"], JN)
jq("j-character-type", "Character Type", "EASY", T, "Read one character and print `Uppercase`, `Lowercase`, `Digit` or `Special`.", "One character.", "One word.", "A visible character.",
   "if (c >= 'A' && c <= 'Z') System.out.println(\"Uppercase\");\nelse if (c >= 'a' && c <= 'z') System.out.println(\"Lowercase\");\nelse if (c >= '0' && c <= '9') System.out.println(\"Digit\");\nelse System.out.println(\"Special\");", ["A", "z", "5", "#", "m", "0"], [("char", "c")])
jq("j-quadratic-roots", "Nature of Quadratic Roots", "MEDIUM", T, "For `a x^2 + b x + c = 0` compute the discriminant `b*b - 4*a*c`. Greater than 0: `Real and distinct`; 0: `Real and equal`; less than 0: `Imaginary`.", "One line: `a b c` (a is not 0).", "One answer.", "|values| <= 1000, a != 0",
   'int d = b * b - 4 * a * c;\nif (d > 0) System.out.println("Real and distinct");\nelse if (d == 0) System.out.println("Real and equal");\nelse System.out.println("Imaginary");', ["1 -3 2", "1 2 1", "1 1 1", "2 4 -6", "3 0 3"], [("int", "a b c")])
jq("j-triangle-type", "Triangle Validity and Type", "MEDIUM", T, "Read three sides. If they cannot form a triangle print `Not a triangle`; otherwise `Equilateral` (all equal), `Isosceles` (exactly two equal) or `Scalene`.", "One line with three integers.", "One result.", "1 <= sides <= 10^6",
   'if (a + b <= c || a + c <= b || b + c <= a) System.out.println("Not a triangle");\nelse if (a == b && b == c) System.out.println("Equilateral");\nelse if (a == b || b == c || a == c) System.out.println("Isosceles");\nelse System.out.println("Scalene");', ["5 5 5", "5 5 8", "3 4 5", "1 2 3", "7 7 2"], [("int", "a b c")])
jq("j-calculator-switch", "Calculator with switch", "EASY", T, "Read `a op b` with whole numbers. Use `switch` on `op` for `+ - * / %`. A division or remainder by zero prints `Cannot divide by zero`; another operator prints `Invalid operator`.", "One line: `a op b`.", "The result or a message.", "|a|, |b| <= 10^6",
   "switch (op) {\n    case '+': System.out.println(a + b); break;\n    case '-': System.out.println(a - b); break;\n    case '*': System.out.println((long) a * b); break;\n    case '/': System.out.println(b == 0 ? \"Cannot divide by zero\" : String.valueOf(a / b)); break;\n    case '%': System.out.println(b == 0 ? \"Cannot divide by zero\" : String.valueOf(a % b)); break;\n    default: System.out.println(\"Invalid operator\");\n}", ["8 + 3", "8 - 10", "6 * 7", "17 / 5", "17 % 5", "5 / 0", "5 ^ 2"], [("int", "a"), ("char", "op"), ("int", "b")])
jq("j-month-name", "Month Name", "EASY", T, "Print the name of month 1 to 12 (`January` ... `December`) with `switch`. Anything else prints `Invalid month`.", ONE, "The month.", "|n| <= 100",
   'String[] names = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};\nswitch (n) {\n    case 1: case 2: case 3: case 4: case 5: case 6: case 7: case 8: case 9: case 10: case 11: case 12:\n        System.out.println(names[n - 1]);\n        break;\n    default:\n        System.out.println("Invalid month");\n}', ["1", "5", "12", "0", "13"], JN)
jq("j-weekday-weekend", "Weekday or Weekend", "EASY", T, "Read a day number (1 = Monday ... 7 = Sunday). Use switch fall-through: 1 to 5 print `Weekday`, 6 and 7 print `Weekend`, anything else `Invalid day`.", ONE, "One word.", "|n| <= 100",
   'switch (n) {\n    case 1: case 2: case 3: case 4: case 5:\n        System.out.println("Weekday");\n        break;\n    case 6: case 7:\n        System.out.println("Weekend");\n        break;\n    default:\n        System.out.println("Invalid day");\n}', ["1", "5", "6", "7", "0", "9"], JN)
jq("j-traffic-signal", "Traffic Signal", "EASY", T, "Read `R`, `Y` or `G`. Print `Stop`, `Get ready` or `Go`; any other letter prints `Invalid signal`.", "One uppercase letter.", "One message.", "A letter.",
   "switch (c) {\n    case 'R': System.out.println(\"Stop\"); break;\n    case 'Y': System.out.println(\"Get ready\"); break;\n    case 'G': System.out.println(\"Go\"); break;\n    default: System.out.println(\"Invalid signal\");\n}", ["R", "Y", "G", "B", "X"], [("char", "c")])
jq("j-vowel-switch", "Vowel Grouping with switch", "EASY", T, "Read one character. With one grouped `case` for the vowels (either case) print `Vowel`; print `Consonant` for any other letter and `Not a letter` otherwise.", "One character.", "One result.", "A visible character.",
   "switch (c) {\n    case 'a': case 'e': case 'i': case 'o': case 'u':\n    case 'A': case 'E': case 'I': case 'O': case 'U':\n        System.out.println(\"Vowel\");\n        break;\n    default:\n        System.out.println(Character.isLetter(c) ? \"Consonant\" : \"Not a letter\");\n}", ["a", "E", "b", "Z", "5", "#"], [("char", "c")])
jq("j-ternary-max-two", "Larger of Two (ternary)", "EASY", T, "Print the larger of two integers with a ternary operator.", "One line with two integers.", "The larger number.", "|values| <= 10^6",
   'System.out.println(a >= b ? a : b);', ["3 9", "9 3", "-4 -9", "5 5", "0 -1"], [("int", "a b")])
jq("j-ternary-abs", "Absolute Value (ternary)", "EASY", T, "Print the absolute value of an integer with a ternary operator.", ONE, "The absolute value.", "|n| <= 10^9",
   'System.out.println(n < 0 ? -n : n);', ["-5", "5", "0", "-1000000", "77"], JN)
jq("j-signum", "Signum with Nested Ternary", "EASY", T, "Print `1` for a positive number, `-1` for a negative one and `0` for zero, using nested ternary operators.", ONE, "`1`, `-1` or `0`.", "|n| <= 10^9",
   'System.out.println(n > 0 ? 1 : (n < 0 ? -1 : 0));', ["9", "-9", "0", "1", "-1000"], JN)
jq("j-ternary-pass-fail", "Pass or Fail (ternary)", "EASY", T, "Print `Pass` for marks of 40 or more, otherwise `Fail`, using a ternary.", "One integer 0 to 100.", "`Pass` or `Fail`.", "0 <= n <= 100",
   'System.out.println(n >= 40 ? "Pass" : "Fail");', ["75", "40", "39", "0", "100"], JN)
jq("j-driving-eligibility", "Driving Eligibility (ternary)", "EASY", T, "A person aged 18 or more can drive. Print `Eligible for a licence` or `Not eligible` with a ternary.", "One integer: age.", "One line.", "0 <= age <= 150",
   'System.out.println(n >= 18 ? "Eligible for a licence" : "Not eligible");', ["18", "17", "45", "0", "100"], JN)
jq("j-divisible-5-and-11", "Divisible by 5 and 11", "EASY", T, "Print `Yes` if the number is divisible by both 5 and 11, otherwise `No`.", ONE, "`Yes` or `No`.", "|n| <= 10^9",
   'if (n % 5 == 0 && n % 11 == 0) System.out.println("Yes");\nelse System.out.println("No");', ["55", "10", "110", "33", "0"], JN)
jq("j-century-year", "Century Year", "EASY", T, "A century year ends in two zeros. Print `Century year` or `Not a century year`.", "One positive integer.", "One line.", "1 <= n <= 9999",
   'if (n % 100 == 0) System.out.println("Century year");\nelse System.out.println("Not a century year");', ["1900", "2024", "2000", "100", "1999"], JN)
jq("j-digit-count-class", "Single or Multi-Digit", "EASY", T, "Ignore the sign and print `Single digit` (0 to 9), `Two digits` (10 to 99) or `Three or more digits`.", ONE, "One result.", "|n| <= 10^9",
   'int v = Math.abs(n);\nif (v < 10) System.out.println("Single digit");\nelse if (v < 100) System.out.println("Two digits");\nelse System.out.println("Three or more digits");', ["7", "-3", "10", "99", "100", "-12345"], JN)
jq("j-bmi-category", "BMI Category", "MEDIUM", T, "Read weight (kg) and height (m). BMI is `weight / (height * height)`. Below 18.5 `Underweight`, below 25 `Normal`, below 30 `Overweight`, otherwise `Obese`.", "One line: `weight height`.", "One category.", "Positive decimals",
   'double bmi = w / (h * h);\nif (bmi < 18.5) System.out.println("Underweight");\nelse if (bmi < 25) System.out.println("Normal");\nelse if (bmi < 30) System.out.println("Overweight");\nelse System.out.println("Obese");', ["50 1.8", "70 1.75", "85 1.75", "110 1.7", "60 1.65"], [("double", "w h")])
jq("j-electricity-bill", "Electricity Bill Slabs", "MEDIUM", T, "The first 50 units cost 3 each, the next 100 (51 to 150) cost 4 each and every unit above 150 costs 6. Print the total bill.", "One integer: units used.", "The bill.", "0 <= units <= 10^5",
   'int bill;\nif (n <= 50) bill = n * 3;\nelse if (n <= 150) bill = 150 + (n - 50) * 4;\nelse bill = 150 + 400 + (n - 150) * 6;\nSystem.out.println(bill);', ["30", "50", "100", "150", "200", "0"], JN)
jq("j-income-tax", "Income Tax Slabs", "MEDIUM", T, "Tax is progressive: nothing up to 300000; 5% of the part from 300001 to 600000; 10% of the part from 600001 to 900000; 15% of the part from 900001 to 1200000; 20% of everything above 1200000. Print the tax (integer, drop any fraction).", "One integer: income.", "The tax.", "0 <= income <= 10^8",
   'long tax;\nif (n <= 300000) tax = 0;\nelse if (n <= 600000) tax = (n - 300000) * 5 / 100;\nelse if (n <= 900000) tax = 15000 + (n - 600000) * 10 / 100;\nelse if (n <= 1200000) tax = 45000 + (n - 900000) * 15 / 100;\nelse tax = 90000 + (n - 1200000) * 20 / 100;\nSystem.out.println(tax);', ["250000", "450000", "600000", "800000", "1000000", "1500000"], [("long", "n")])
jq("j-time-greeting", "Greeting by Hour", "EASY", T, "Read the hour (0 to 23). 5 to 11 print `Good morning`, 12 to 16 `Good afternoon`, 17 to 20 `Good evening`, otherwise `Good night`.", ONE, "One greeting.", "0 <= n <= 23",
   'if (n >= 5 && n <= 11) System.out.println("Good morning");\nelse if (n >= 12 && n <= 16) System.out.println("Good afternoon");\nelse if (n >= 17 && n <= 20) System.out.println("Good evening");\nelse System.out.println("Good night");', ["8", "13", "19", "23", "3", "5", "12"], JN)
jq("j-age-group", "Age Group", "EASY", T, "Under 13 `Child`, 13 to 19 `Teenager`, 20 to 59 `Adult`, 60 or more `Senior`.", "One integer: age.", "One word.", "0 <= age <= 150",
   'if (n < 13) System.out.println("Child");\nelse if (n <= 19) System.out.println("Teenager");\nelse if (n <= 59) System.out.println("Adult");\nelse System.out.println("Senior");', ["5", "13", "25", "60", "19", "59"], JN)
jq("j-water-state", "State of Water", "EASY", T, "At 0 degrees Celsius or below water is `Ice`; above 0 and below 100 it is `Liquid`; at 100 or more it is `Steam`.", ONE, "One word.", "|n| <= 1000",
   'if (n <= 0) System.out.println("Ice");\nelse if (n < 100) System.out.println("Liquid");\nelse System.out.println("Steam");', ["-5", "0", "25", "99", "100", "150"], JN)
jq("j-discount-tiers", "Discount Tiers", "EASY", T, "A purchase of 10000 or more gets 25% off, 5000 or more 15% off, 1000 or more 5% off, otherwise nothing. Print the amount to pay with two decimals.", "One integer: purchase total.", "The payable amount.", "0 <= total <= 10^7",
   'double rate = n >= 10000 ? 0.25 : n >= 5000 ? 0.15 : n >= 1000 ? 0.05 : 0;\nSystem.out.printf("%.2f%n", n * (1 - rate));', ["500", "1000", "5000", "10000", "7777"], JN)
jq("j-card-suit", "Card Suit", "EASY", T, "Read `S`, `H`, `D` or `C` and print `Spades`, `Hearts`, `Diamonds` or `Clubs` with `switch`. Anything else: `Invalid suit`.", "One uppercase letter.", "One word.", "A letter.",
   "switch (c) {\n    case 'S': System.out.println(\"Spades\"); break;\n    case 'H': System.out.println(\"Hearts\"); break;\n    case 'D': System.out.println(\"Diamonds\"); break;\n    case 'C': System.out.println(\"Clubs\"); break;\n    default: System.out.println(\"Invalid suit\");\n}", ["S", "H", "D", "C", "X"], [("char", "c")])
jq("j-department-code", "Department Code", "EASY", T, "Map 1 to `Computer Science`, 2 `Electronics`, 3 `Mechanical`, 4 `Civil` using `switch`. Anything else: `Unknown department`.", ONE, "The department.", "|n| <= 100",
   'switch (n) {\n    case 1: System.out.println("Computer Science"); break;\n    case 2: System.out.println("Electronics"); break;\n    case 3: System.out.println("Mechanical"); break;\n    case 4: System.out.println("Civil"); break;\n    default: System.out.println("Unknown department");\n}', ["1", "2", "3", "4", "9"], JN)
jq("j-shape-area-menu", "Shape Area Menu", "MEDIUM", T, "Read a choice and its numbers: 1 circle (radius), 2 rectangle (length, width), 3 triangle (base, height), 4 square (side). Print the area with two decimals (use `Math.PI`). Any other choice prints `Invalid choice`.", "One line: the choice followed by its numbers.", "The area.", "Numbers are decimals.",
   'switch (choice) {\n    case 1: { double r = in.nextDouble(); System.out.printf("%.2f%n", Math.PI * r * r); break; }\n    case 2: System.out.printf("%.2f%n", in.nextDouble() * in.nextDouble()); break;\n    case 3: System.out.printf("%.2f%n", 0.5 * in.nextDouble() * in.nextDouble()); break;\n    case 4: { double s = in.nextDouble(); System.out.printf("%.2f%n", s * s); break; }\n    default: System.out.println("Invalid choice");\n}', ["1 2", "2 4 5", "3 6 3", "4 2.5", "5"], [("int", "choice")])
jq("j-compass-direction", "Compass Direction", "EASY", T, "Read `N`, `S`, `E` or `W` and print `North`, `South`, `East` or `West`. Anything else: `Invalid direction`.", "One uppercase letter.", "One word.", "A letter.",
   "switch (c) {\n    case 'N': System.out.println(\"North\"); break;\n    case 'S': System.out.println(\"South\"); break;\n    case 'E': System.out.println(\"East\"); break;\n    case 'W': System.out.println(\"West\"); break;\n    default: System.out.println(\"Invalid direction\");\n}", ["N", "S", "E", "W", "Q"], [("char", "c")])
jq("j-rating-feedback", "Rating Feedback", "EASY", T, "Rating 1 `Poor`, 2 `Fair`, 3 `Good`, 4 `Very good`, 5 `Excellent`. Anything else: `Invalid rating`.", ONE, "The feedback.", "|n| <= 100",
   'switch (n) {\n    case 1: System.out.println("Poor"); break;\n    case 2: System.out.println("Fair"); break;\n    case 3: System.out.println("Good"); break;\n    case 4: System.out.println("Very good"); break;\n    case 5: System.out.println("Excellent"); break;\n    default: System.out.println("Invalid rating");\n}', ["1", "3", "5", "0", "6"], JN)
jq("j-divisible-3-or-7", "Divisible by 3 or 7", "EASY", T, "Print `Yes` if the number is divisible by 3 or by 7, otherwise `No`.", ONE, "`Yes` or `No`.", "|n| <= 10^9",
   'if (n % 3 == 0 || n % 7 == 0) System.out.println("Yes");\nelse System.out.println("No");', ["9", "14", "10", "21", "1"], JN)
jq("j-password-length", "Password Length", "EASY", T, "Read a password (no spaces). Print `Valid` when it has at least 8 characters, otherwise `Too short`.", "One word of up to 100 characters.", "`Valid` or `Too short`.", "1 <= length <= 100",
   'if (w.length() >= 8) System.out.println("Valid");\nelse System.out.println("Too short");', ["abcdefgh", "abc", "NextByte1", "1234567", "passw0rd!"], [("String", "w")])
jq("j-coordinate-quadrant", "Quadrant of a Point", "EASY", T, "Print `Origin` for (0, 0), `On an axis` if exactly one of x, y is 0, otherwise the quadrant `I`, `II`, `III` or `IV`.", "One line: `x y`.", "One answer.", "|x|, |y| <= 10^6",
   'if (x == 0 && y == 0) System.out.println("Origin");\nelse if (x == 0 || y == 0) System.out.println("On an axis");\nelse if (x > 0 && y > 0) System.out.println("I");\nelse if (x < 0 && y > 0) System.out.println("II");\nelse if (x < 0 && y < 0) System.out.println("III");\nelse System.out.println("IV");', ["3 4", "-3 4", "-3 -4", "3 -4", "0 0", "0 5"], [("int", "x y")])
jq("j-library-fine", "Library Fine", "MEDIUM", T, "0 or fewer days late: no fine. Days 1 to 5: 1 per day. Days 6 to 15: the 5 for the first five days plus 2 per day after day 5. More than 15 days: the fine for day 15 plus 5 per day after day 15. Print the fine.", "One integer: days late.", "The fine.", "|n| <= 10^4",
   'int fine;\nif (n <= 0) fine = 0;\nelse if (n <= 5) fine = n;\nelse if (n <= 15) fine = 5 + (n - 5) * 2;\nelse fine = 25 + (n - 15) * 5;\nSystem.out.println(fine);', ["0", "3", "5", "10", "15", "20"], JN)
jq("j-smallest-of-four", "Smallest of Four", "EASY", T, "Read four integers and print the smallest using comparisons.", "One line with four integers.", "The smallest.", "|values| <= 10^6",
   'int m = a;\nif (b < m) m = b;\nif (c < m) m = c;\nif (d < m) m = d;\nSystem.out.println(m);', ["4 2 8 6", "1 1 1 1", "-1 5 3 -7", "9 8 7 6", "0 0 -1 0"], [("int", "a b c d")])
